def point_type(name, fields, srid_map):
    """
    Dynamically create a Point subclass.

    Args:
    name (str): The name of the Point subclass.
    fields (dict): A dictionary where keys are the fields of the point, and values are their data types.
    srid_map (dict): A dictionary mapping SRID to coordinate reference systems.

    Returns:
    type: The dynamically created Point subclass.
    """
    class Point(object):
        __slots__ = fields.keys()

        def __init__(self, **kwargs):
            for k, v in kwargs.items():
                setattr(self, k, v)

        @classmethod
        def to_srid(cls, point, srid):
            if srid not in srid_map:
                raise ValueError(f"SRID {srid} is not valid for this coordinate reference system.")
            return point.transform(srid_map[srid]).coords

    return Point
