        if c.startswith('#!'):
            # Normalize the shebang for Windows
            shebang_parts = c.split('\n')
            normalized_shebang = shebang_parts[0] + ' ' + os.path.normpath(shebang_parts[1])
            normalized_cmd.append(normalized_shebang)
        else:
            # Use the original command if it's not a shebang
            normalized_cmd.append(c)

