from collections import OrderedDict

class TTLCache:
    def __init__(self, maxsize=128, ttl=600, timer=time.monotonic, typed=False):
        self.maxsize = maxsize
        self.ttl = ttl
        self.timer = timer
        self.ttl_cache = OrderedDict()
        self.key_to_original = {}

