def update_last_applied_manifest_list_from_resp(
    last_applied_manifest,
    observer_schema,
    response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest`` from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    if not isinstance(last_applied_manifest, list):
        raise ValueError("last_applied_manifest must be a list")
    if not isinstance(observer_schema, list):
        raise ValueError("observer_schema must be a list")
    if not isinstance(response, list):
        raise ValueError("response must be a list")

    for observation in response:
        if observation["type"] == "connectivity":
            # Initialize or update connectivity-related fields
            connection_info = observation["info"]
            for field in connection_info:
                if field not in last_applied_manifest["connection_info"]:
                    last_applied_manifest["connection_info"][field] = field

        elif observation["type"] == "storage":
            # Initialize or update storage-related fields
            storage_details = observation["details"]
            for field in storage_details:
                if field not in last_applied_manifest["storage"]:
                    last_applied_manifest["storage"][field] = field

        else:
            # Initialize or update other type of fields
            field_value = observation["value"]
            if field_value not in last_applied_manifest:
                last_applied_manifest[field_value] = field_value

    return last_applied_manifest
