                if line.startswith('VERSIONER_VERSION'):
                    self.version = line.split('=')[1].strip().strip("'")
                if line.startswith('VERSIONER_REVISION'):
                    self.revision = line.split('=')[1].strip().strip("'")
                if line.startswith('VERSIONER_IDENTIFIER'):
                    self.identifier = line.split('=')[1].strip().strip("'")
                if line.startswith('VERSIONER_TAG_PREFIX'):
                    self.tag_prefix = line.split('=')[1].strip().strip("'")
                if line.startswith('VERSIONER_BRANCH_PREFIX'):
                    self.branch_prefix = line.split('=')[1].strip().strip("'")

class Versioneer:
