import ruamel.yaml

def deep_merge_nodes(nodes):
    """Given a nested borgmatic configuration data structure as a list of tuples in the form of

    (...)

    For instance, given node values of:

        (...)

    ... the returned result would be:

        (...)

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """

    # Create a dictionary to store merged configuration
    merged_config = {}

    # Iterate over the nodes and merge them
    for key, value in nodes:
        key_str = key.value

        # If the key is not in the dictionary, add it with a copy of the value
        if key_str not in merged_config:
            if isinstance(value, ruamel.yaml.nodes.MappingNode):
                merged_config[key_str] = ruamel.yaml.nodes.MappingNode()
            else:
                merged_config[key_str] = value.deepcopy()

        # Merge the value with the existing value in the dictionary
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            for k, v in value.items():
                existing_value = merged_config[key_str].get(k, v)
                if isinstance(existing_value, ruamel.yaml.nodes.MappingNode):
                    if isinstance(v, ruamel.yaml.nodes.MappingNode):
                        merged_config[key_str].set_item(k, deep_merge_nodes([(k, v)]) + existing_value.pairs)
                    else:
                        merged_config[key_str].set_item(k, deep_merge_nodes([(k, v)]))
                else:
                    merged_config[key_str].set_item(k, deep_merge_nodes([(k, existing_value), (k, v)]))
        else:
            merged_config[key_str] = deep_merge_nodes([(key, value)])

    return list(merged_config.items())
