class MappingNode:
    def __init__(self, tag: str, value: List[Tuple]):
        self.tag = tag
        self.value = value

    def __repr__(self):
        return f"MappingNode(tag='{self.tag}', value={self.value})"

class ScalarNode:
    def __init__(self, tag: str, value: str):
        self.tag = tag
        self.value = value

    def __repr__(self):
        return f"ScalarNode(tag='{self.tag}', value='{self.value}')"

def deep_merge_nodes(nodes):
