    for unit in ["", "K", "M", "G"]:
        if unit in size:
            size = size.replace(unit, "")
            magnitude += 1

    value = float(size)
    if magnitude == 0:
        return int(value)
    power = 2 ** (magnitude * 10)
    return int(value * power)

