def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not isinstance(archive_path, str):
        raise TypeError("archive_path must be a string")

    try:
        archive_path = Path(archive_path)
    except ValueError:
        raise ValueError("archive_path must be a valid file path")

    if not archive_path.is_file():
        raise FileNotFoundError(f"File {archive_path} does not exist")

    if filename is None:
        filename = archive_path.stem

    if not isinstance(tmp_path, (PosixPath, str)):
        raise TypeError("tmp_path must be a string or a PosixPath object")

    try:
        with subprocess.Popen(['tar', '-xzvf', archive_path.name], cwd=str(tmp_path), stdout=subprocess.PIPE, stderr=subprocess.PIPE) as process:
            output, error = process.communicate()
            if process.returncode != 0:
                raise subprocess.CalledProcessError(process.returncode, error.decode())
    except FileNotFoundError:
        raise FileNotFoundError(f"Make sure tar is installed on your system")

    return str(archive_path.with_suffix('.repo'))
