import subprocess

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    try:
        # Check if the archive file exists
        if not os.path.exists(archive_path):
            raise FileNotFoundError(f"The archive file {archive_path} does not exist.")

        # Create a new directory to extract the archive
        tmp_dir = os.path.join(tmp_path, os.path.basename(archive_path))
        os.makedirs(tmp_dir, exist_ok=True)

        # Extract the archive using the appropriate extraction tool
        extraction_command = [("tar", "-xzf", archive_path, "-C", tmp_dir), ("unzip", "-q", archive_path, "-d", tmp_dir)]

        subprocess.run(extraction_command, check=True)

        # Get the URL of the origin repository
        # Assuming the repository files are in a 'repo' directory within the extracted archive
        repo_url = os.path.join(tmp_dir, "repo", "origin")

        return repo_url
    except FileNotFoundError as e:
        return str(e)
    except subprocess.CalledProcessError as e:
        return str(e)
