from rdflib import URIRef, Graph

def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if roots is None:
        roots = set()
        for child, parent in graph:
            if child == prop:
                roots.add(parent)

    visited = set()
    for root in roots:
        find_roots_in_depth(graph, root, visited)

    return roots

def find_roots_in_depth(graph: Graph, node: "Node", visited: set):
    visited.add(node)
    for child in graph:
        if child[0] == node and child[1].uri != prop.uri:  # Avoid the recursive call for the root itself
            find_roots_in_depth(graph, child[1], visited)
