    def __init__(self, bins, context=None):
        self.bins = bins
        self.context = context

class graph:
    def __init__(self, points):
        self.points = points

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if not isinstance(hist, histogram):
        raise TypeError("hist must be a histogram object")

    if make_value is not None and not callable(make_value):
        raise TypeError("make_value must be a callable function")

    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be either 'left', 'right', or 'middle'")

    if scale is not None and not isinstance(scale, bool):
        raise TypeError("scale must be a boolean")

    if scale:
        scale_factor = hist.bins[-1] - hist.bins[0]
        hist = [bin_ / scale_factor for bin_ in hist.bins]

    points = []
    for bin_ in hist:
        if make_value is not None:
            x, *y = make_value(bin_)
            y = [y] if len(y) == 1 else y
            y = [value * scale_factor for value in y if np.isfinite(value)]
        else:
            x = bin_
            y = bin_ if np.isfinite(bin_) else float("nan")

        if get_coordinate == "left":
            points.append((x, y))
        elif get_coordinate == "right":
            points.append((x + scale_factor, y))
        elif get_coordinate == "middle":
            points.append(((x + scale_factor) / 2, y))

    return graph(points)
