def _verify(iface, candidate, tentative=False, vtype=None):
    verifications_passed = True
    error_messages = []

    # Step 1: Verify that the candidate claims to provide the interface.
    provided = candidate.providedBy(iface) if not tentative else None
    if vtype is not None:
        if provided != vtype:
            error_messages.append(f"Expected candidate to provide type {vtype}, but got {provided}.")

    # Step 2: Verify that the candidate defined all necessary methods.
    required_methods = [iface for name in iface.dispatch.all_methods() if not name.startswith('_')]
    if needed_methods:
        missing_methods = required_methods - candidate.walkIncontext()[iface]
        if missing_methods:
            error_messages.append(f"Missing methods: {', '.join(missing_methods)}")

    # Step 3: Verify that the candidate defined all necessary attributes.
    required_attributes = iface.dispatch.all_attributes()
    if required_attributes:
        missing_attributes = required_attributes - candidate.walkIncontext()[iface]
        if missing_attributes:
            error_messages.append(f"Missing attributes: {', '.join(missing_attributes)}")

    # Step 4: Verify the method signatures.
    if not tentative:
        for method in candidate.walkIncontext()[iface][required_methods]:
            try:
                method(tuple())
            except TypeError as e:
                error_messages.append(f"Method {method.__name__} has an invalid signature.")

    # Check if any errors were found
    if error_messages:
        if len(error_messages) == 1:
            raise Invalid(error_messages[0])
        raise Invalid('; '.join(error_messages))
    return verifications_passed
