from zope.interface.exceptions import Invalid

def verifyObject(iface, candidate, tentative=False):
    try:
        provided_by = candidate.providedBy
        if tentative:
            if hasattr(candidate, '__implements__'):
                provided_by = candidate.__implements__
            else:
                provided_by = False
    except AttributeError:
        provided_by = False

    if not provided_by:
        raise Invalid(f"'{candidate.__class__.__name__}' does not claim to provide the interface.")

    try:
        methods_needed = iface.implementedBy(candidate)
    except AttributeError:
        methods_needed = []

    if len(methods_needed) == 0:
        return True

    actual_methods = set(dir(candidate))
    methods_in_interface = set(methods_needed)

    missing_methods = methods_in_interface.difference(actual_methods)
    if len(missing_methods) == 0:
        return True

    candidate_methods = {k: getattr(candidate, k) for k in missing_methods}
    actual_methods = {k: getattr(candidate, k) for k in actual_methods}

    missing_method_errors = []
    for k, v in candidate_methods.items():
        try:
            v(*())
        except TypeError as e:
            missing_method_errors.append((k, str(e)))

    if len(missing_method_errors) == 0:
        return True

    if len(missing_method_errors) == 1:
        raise Invalid(f"'{candidate.__class__.__name__}' does not override all necessary methods.\n"
                      f"'{missing_method_errors[0][0]}' does not override the method.\n"
                      f"Error: {missing_method_errors[0][1]}")

    errors = missing_method_errors
    if len(errors) == 1:
        raise Invalid(f"'{candidate.__class__.__name__}' does not override necessary method, "
                      f"'{errors[0][0]}' does not override the method.\n"
                      f"Error: {errors[0][1]}")

    raise Invalid(f"'{candidate.__class__.__name__}' does not override all necessary methods.\n"
                  f"{', '.join([f"'{k}' does not override the method." for k, _ in errors])}")
