    Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_code_block = False
    current_tag = ""
    replaced_text = text

    for char in text:
        if char == '<':
            if in_code_block:
                continue
            elif current_tag:
                tags.add(current_tag)
                current_tag = ""
            in_code_block = True
        elif in_code_block:
            if char == '>':
                tags.add(current_tag)
                current_tag = ""
                in_code_block = False
            else:
                current_tag += char
        elif current_tag:
            if replacer:
                current_tag = replacer(current_tag)
        else:
            replaced_text = text[:text.index(char)] + (replacer(current_tag) if replacer else current_tag) + text[text.index(char) + 1:]

    if current_tag:
        tags.add(current_tag)

    return tags, replaced_text
