        process = subprocess.Popen(params, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        output, error = process.communicate()

        # Check if the command was successful
        if process.returncode == 0:
            return output
        else:
            raise Exception(f"Ansible command failed with return code {process.returncode}, error: {error.decode('utf-8')}")
    except ValueError as e:
        raise e
    except Exception as e:
        raise e

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    try:
        ansible_command = ['ansible-playbook'] + cli_args
        ansible_command.extend(['-i', os.path.join(ir_workspace.local_files_path, 'inventory.yaml')])
        ansible_command.extend(['--extra-vars', str(vars_dict)])

        result = subprocess.run(ansible_command, capture_output=True, text=True, check=True, env={**os.environ, 'INFRADIR': ir_workspace.local_files_path})

        return result.stdout
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Error running Ansible playbook: {e.stderr}")
    except Exception as e:
        raise RuntimeError(f"An unexpected error occurred: {e}")

